#!/usr/bin/env node
// Art outbox CLI (spec §6.1(6), §11.5; independent audit P0-1/2/3/5). Every job is GENERATED by engine/art_bridge/art_intake.mjs#planJobs from
// the action/shot graph + the real manifest check; nothing here is hand-edited. Masters compile now (skill prepare_first_pass.py); derived
// jobs compile only when their master's approval receipt verifies, with the approved master bytes as the mandatory edit reference.
//   export  --film DIR [--out DIR]
//   status  [--out DIR]
//   submit  --film DIR --job ID [--out DIR]                                      (provider; WAITING_FOR_GPT_ART when none is configured)
//   ingest-master --film DIR --asset ID --file PNG --landmarks JSON --provenance P
//   check-design --film DIR --asset ID       Stage 3 BEFORE gate report (method fidelity, applicability, molecular, agreement, grounding)
//   review-design --film DIR --asset ID --reviewer NAME --verdict V [--human]   art-director design decision (HUMAN only via interactive TTY)
//   review-story|review-direction --film DIR --reviewer NAME --verdict V [--human]   HUMAN story / experience-direction receipts (content-hash bound)
//   review-master --film DIR --identity ID --reviewer NAME --verdict APPROVED|REJECTED|REVISE_AT_ART_SOURCE [--notes T] [--scope-note T]
//   ingest-part   --film DIR --asset ID --file PNG --landmarks JSON --provenance P
//   review-part   --film DIR --asset ID --reviewer NAME --verdict V
//   approve-state --film DIR --rig ID --state ID --reviewer NAME --verdict V
//   approve-edge  --film DIR --rig ID --from S --to S --reviewer NAME --verdict V
//   export-gpt-job --film DIR --job ID [--stage K]   EXTERNAL_GPT_OPERATOR_HANDOFF bundle (same contract authority as submit; no API call)
//   import-gpt-candidates --film DIR --bundle DIR    operator-returned PNGs → sealed OPERATOR-ATTESTED candidates (approves nothing)
//   select-candidate --job ID --stage K --candidate KEY16:IDX   explicit selection by candidate id under a fenced lock
//   resume        --film DIR [--out DIR]                                         (= export: recomputes readiness, invalidation, compiles ready jobs)
import fs from "node:fs"; import path from "node:path"; import url from "node:url"; import { spawnSync } from "node:child_process";
import { compileArtJob, dependencyDigest } from "../art_bridge/art_requests.mjs";
import * as C from "../art_bridge/art_contract.mjs";
import { compileFilmContracts } from "./compile_film_contracts.mjs";
import { genDir, materialize, writeOnce, writeCurrent } from "../art_bridge/outbox_store.mjs";
import { discoverProvider } from "../art_bridge/providers/image_provider.mjs";
import * as I from "../art_bridge/art_intake.mjs";

const here = path.dirname(url.fileURLToPath(import.meta.url)), REPO = path.resolve(here, "..", "..");
const rel = (f) => path.relative(REPO, path.resolve(f)).split(path.sep).join("/");

/** contract context for a job: the two-way art-to-motion contract applies to CHARACTER canonical masters (art_contract.mjs) */
export { contractContext as contractFor } from "../art_bridge/art_contract.mjs";
import { contractContext as contractFor } from "../art_bridge/art_contract.mjs";
/** exportOutbox — content-addressed, never destructive (directive E3). Each job generation = dependency digest over motion context, design,
 *  skill, source clauses, witnesses, repair memory, approved master, story/direction content and provider size. Same digest ⇒ reused
 *  byte-identical; changed digest ⇒ a NEW generation beside the old one (old requests, candidates and receipts are kept). Story approval
 *  comes only from a verified story receipt — never from doc.status. */
export async function exportOutbox({ film, out = path.join(REPO, "hybrid_v2", "art_outbox") }) {
  const FILM = path.resolve(film), filmContracts = compileFilmContracts({ film: FILM }); // story / actions / continuity / attention / demand BEFORE art
  const { check, jobs, doc } = await I.planJobs({ film: FILM }), readiness = new Map((await I.resumeDependentJobs({ film: FILM })).map((r) => [r.asset, r]));
  const provider = discoverProvider(), caps = await provider.capabilities(), size = process.env.IMAGE_PROVIDER_SIZE || "1536x1024";
  for (const d of ["jobs", "inbox", "compiled"]) fs.mkdirSync(path.join(out, d), { recursive: true });
  const story = C.scopeApprovalStatus(FILM, doc, "story"), direction = C.scopeApprovalStatus(FILM, doc, "direction"), storyB = C.scopeBundle(FILM, "story"), dirB = C.scopeBundle(FILM, "direction");
  const byRoot = new Map(jobs.map((j) => [j.root_dependency, j])), index = [], current = fs.existsSync(path.join(out, "CURRENT.json")) ? JSON.parse(fs.readFileSync(path.join(out, "CURRENT.json"), "utf8")) : {};
  const mem = path.join(FILM, "learning", "REPAIR_MEMORY.json");
  for (const j of jobs) {
    const rd = readiness.get(j.root_dependency), masterJob = j.derived_from ? byRoot.get(j.derived_from) : null;
    const designF = path.join(FILM, "art_designs", `${j.derived_from || j.root_dependency}.design.json`), design = fs.existsSync(designF) ? JSON.parse(fs.readFileSync(designF, "utf8")) : null;
    const gate = C.gateForJob({ film: FILM, doc, job: j, masterJob });
    let status = j.unused_in_action_graph ? "UNUSED_IN_ACTION_GRAPH" : rd?.status || "WAITING_FOR_GPT_ART";
    const compilable = j.state_kind === "MASTER" ? !["APPROVED", "PENDING_REVIEW"].includes(status) : status === "READY_FOR_SOURCE_ATTACHED_EDIT";
    const dg = dependencyDigest({ job: j, design, repairMemory: mem, editReference: rd?.edit_reference || null, storyBundle: storyB, directionBundle: dirB, size, doc }), digest = dg.digest.slice(0, 24);
    let compiled = null;
    if (!gate.pass) { compiled = { status: "BLOCKED_CONTRACT", failures: gate.failures.map((x) => `${x.code}${x.method ? ":" + x.method : ""}`) }; status = "BLOCKED_CONTRACT"; }
    else if (compilable) {
      const final = genDir(out, "compiled", j.artjob_id, digest);
      try { const m = materialize(final, (tmp) => { const c = compileArtJob(j, { film: FILM, outDir: tmp, repairMemory: mem, masterJob, editReference: rd?.edit_reference || null });
          if (rd?.edit_reference) fs.writeFileSync(path.join(tmp, "EDIT_REFERENCE.json"), JSON.stringify({ mandatory_edit_reference: rd.edit_reference, note: "submit/edit must attach these exact master bytes" }, null, 1)); return c; });
        const brc = JSON.parse(fs.readFileSync(path.join(final, "BRIDGE_REQUEST_CONTRACT.json"), "utf8"));
        compiled = { status: "COMPILED_WAITING_FOR_GPT_ART", generation: digest, prompt_sha256: brc.stages[0].prompt_sha256, stages: brc.stages.length, provider_ready: false, witnesses: (m.result?.witnesses || []).map((w) => `${w.path} ${w.sha256.slice(0, 12)} ${w.verified ? "verified" : "UNVERIFIED"}`) };
        if (j.state_kind === "MASTER") status = "WAITING_FOR_APPROVALS_THEN_GPT_ART"; }
      catch (e) { compiled = { status: "COMPILE_BLOCKED", error: e.toJSON ? e.toJSON() : String(e) }; status = "BLOCKED_COMPILE"; }
    } else if (compilable && !design) status = "BLOCKED_NO_DESIGN_BRIEF";
    const rec = { ...j, status, generation: digest, dependency_parts_digest: dg.digest, gate: { pass: gate.pass, family: gate.family ?? null, failures: gate.failures, required_methods: gate.required_methods.map((x) => x.method) }, readiness: rd || null,
      blocked_on: [...(story.ok ? [] : [`STORY_APPROVAL_REQUIRED: ${story.reason}`]), ...(direction.ok ? [] : [`DIRECTION_APPROVAL_REQUIRED: ${direction.reason}`]), ...(gate.pass ? [] : ["ART_CONTRACT_REFUSED"]), ...(caps.available ? [] : [`NO_IMAGE_PROVIDER: ${caps.blocker}`]), ...(j.derived_from && status !== "READY_FOR_SOURCE_ATTACHED_EDIT" ? [`MASTER_APPROVAL: ${j.derived_from}`] : [])],
      compiled_request: compiled, inbox: { expected_file: `inbox/${j.artjob_id}.png`, landmarks_sidecar: `inbox/${j.artjob_id}.landmarks.json`, format: j.motion_context.alpha_requirement === "OPAQUE" ? "lossless PNG, opaque" : "lossless PNG with real alpha (never a keyed background)" } };
    // the generation record is IMMUTABLE content (job + dependency digest + gate verdict); mutable status lives in CURRENT.json / OUTBOX_INDEX.json
    const { triggered_by, registration_contract, dependents, ...content } = j, immutable = { ...content, generation: digest, dependency_parts_digest: dg.digest, gate: rec.gate };
    writeOnce(path.join(genDir(out, "jobs", j.artjob_id, digest), "job.json"), JSON.stringify(immutable, null, 1));
    current[j.artjob_id] = { digest, status, blocked_on: rec.blocked_on, compiled: compiled?.status || null, readiness: rd?.status || null, mutable: { triggered_by, registration_contract, dependents } };
    index.push({ ...(compiled?.error ? { blocked_reason: compiled.error.human_readable_reason ?? compiled.error.reason ?? String(compiled.error.message ?? compiled.error) } : compiled?.failures ? { blocked_reason: compiled.failures.join(", ") } : {}), artjob_id: j.artjob_id, asset: j.root_dependency, state_kind: j.state_kind, asset_kind: j.asset_kind, medium: j.medium.medium, order: j.manufacturing_order, derived_from: j.derived_from, status, generation: digest, gate_pass: gate.pass, family: gate.family ?? null, frame_ranges: j.motion_context.frame_ranges, triggers: j.triggered_by.length, motion_context_sha256: j.motion_context_sha256, compiled: compiled?.status || null, prompt_sha256: compiled?.prompt_sha256 || null, witnesses: compiled?.witnesses || [] });
  }
  writeCurrent(out, current);
  for (const r of index.filter((x) => x.witnesses.length)) { const paths = r.witnesses.map((w) => path.join(REPO, w.split(" ")[0])), sheet = path.join(out, "contact_sheets", `${r.artjob_id}__${r.generation}.png`); fs.mkdirSync(path.dirname(sheet), { recursive: true });
    if (!fs.existsSync(sheet)) spawnSync(process.env.PYTHON || "python", ["-I", "-c", "import sys\nfrom PIL import Image\nims=[Image.open(p).convert('RGB') for p in sys.argv[2:]]\nh=360\nims=[i.resize((int(i.width*h/i.height),h)) for i in ims]\nW=sum(i.width for i in ims)+10*(len(ims)-1)\nc=Image.new('RGB',(W,h),(255,255,255))\nx=0\nfor i in ims:\n  c.paste(i,(x,0)); x+=i.width+10\nc.save(sys.argv[1])", sheet, ...paths]); r.contact_sheet = rel(sheet); }
  const summary = { status: "WAITING_FOR_GPT_ART", generated_by: "engine/art_bridge/art_intake.mjs#planJobs (no hand-edited jobs)", generated_at: new Date().toISOString(), film: rel(FILM), storage: "content-addressed: jobs/<id>/<generation>/job.json, compiled/<id>/<generation>/ (never deleted); CURRENT.json points at the current generation",
    manifest_check: { pass: check.pass, gates: check.gates, error_counts: check.errors.reduce((m, e) => ((m[e.code] = (m[e.code] || 0) + 1), m), {}) },
    film_contracts: { report: "story/FILM_CONTRACT_REPORT.json", blockers: filmContracts.blockers, revision: filmContracts.revision },
    provider: { ...provider.report, capabilities: caps }, story_approval: story.ok ? "APPROVED" : `NOT_APPROVED (${story.status})`, direction_approval: direction.ok ? "APPROVED" : `NOT_APPROVED (${direction.status})`, jobs: index.length,
    by_order: index.reduce((m, r) => ((m[r.order] = (m[r.order] || 0) + 1), m), {}), by_status: index.reduce((m, r) => ((m[r.status] = (m[r.status] || 0) + 1), m), {}), gate_blocked: index.filter((r) => !r.gate_pass).length,
    compiled: index.filter((r) => r.compiled === "COMPILED_WAITING_FOR_GPT_ART").length, empty_frame_ranges_with_triggers: jobs.filter((j) => j.triggered_by.some((t) => t.frame_range) && !j.motion_context.frame_ranges.length).length, unused_in_action_graph: jobs.filter((j) => j.unused_in_action_graph).map((j) => j.root_dependency), index };
  fs.writeFileSync(path.join(out, "OUTBOX_INDEX.json"), JSON.stringify(summary, null, 1));
  fs.writeFileSync(path.join(out, "INSTRUCTIONS_FOR_IMAGE_PRODUCTION.md"), instructions(summary));
  fs.writeFileSync(path.join(out, "inbox", "README.md"), "Deliver `<ARTJOB_ID>.png` (lossless PNG; real alpha where required) + `<ARTJOB_ID>.landmarks.json` = {\"landmarks\": {name: [x,y] in delivered pixels}, \"reviewed_by\": NAME, \"method\": TEXT}.\nMasters: `art_outbox.mjs ingest-master ...` then an explicit `review-master`. Derived states: only after the master's approval verifies, `ingest-part` then `review-part`.\nNothing in this folder is ever generated by Claude.\n");
  return summary;
}

function instructions(s) {
  const masters = s.index.filter((r) => r.state_kind === "MASTER");
  return `# WAITING_FOR_GPT_ART — image production instructions (${s.film})

Status **${s.status}** · story approval **${s.story_approval}** · provider **${s.provider.capabilities.available ? "available" : "NOT AVAILABLE"}** ${s.provider.capabilities.blocker ? `— ${s.provider.capabilities.blocker}` : ""}
Jobs are generated from the action/shot graph by \`engine/art_bridge/art_intake.mjs#planJobs\`; every job carries its exact frame ranges, shots, sockets, pivots, near/far order and camera footprint (jobs with triggers but no frames: ${s.empty_frame_ranges_with_triggers}).

## Order — ${JSON.stringify(s.by_order)} · status ${JSON.stringify(s.by_status)}
1. Story and direction approval first (verified HUMAN receipts: \`art_outbox.mjs review-story|review-direction\`). Jobs are provisional until then.
2. Canonical masters (medium RASTER_MASTER_THEN_SOURCE_ATTACHED_EDITS / CANONICAL_WORLD_PLATE_WITH_OVERSCAN):
${masters.map((m) => `   - \`${m.artjob_id}\` → ${m.asset} · ${m.medium} · ${m.status}${m.contact_sheet ? ` · ${m.contact_sheet}` : ""}`).join("\n")}
   Submit (only after story, direction and design receipts verify): \`node engine/tools/art_outbox.mjs submit --film <film> --job <ID>\`. Requests live in \`compiled/<ID>/<generation>/STAGE_NN_REQUEST.json\` (ordered stages; stage N edits stage N-1's selected output).
3. \`ingest-master\` with reviewed landmarks → measured canonical frame + identity hash; then an explicit \`review-master\` verdict (hash-scoped receipt).
4. \`resume\`: dependents become READY_FOR_SOURCE_ATTACHED_EDIT and compile with the approved master bytes as mandatory edit reference (EDIT_REFERENCE.json).
5. \`ingest-part\` (registration against the approved master; refuses off-axis/misregistered edits) → \`review-part\`, \`approve-state\`, \`approve-edge\`.
6. Any change to master pixels/landmarks makes dependent receipts STALE; \`resume\` lists the re-manufacture/re-review work.
`;
}

if (process.argv[1] && import.meta.url === url.pathToFileURL(path.resolve(process.argv[1])).href) {
  const a = process.argv.slice(2), get = (k) => { const i = a.indexOf(k); return i >= 0 ? a[i + 1] : null; }, out = get("--out") || path.join(REPO, "hybrid_v2", "art_outbox"), film = get("--film"), cmd = a[0];
  const show = (r) => { console.log(JSON.stringify(r, null, 1)); return r; };
  try {
    if ((cmd === "export" || cmd === "resume") && film) { const s = await exportOutbox({ film, out }); console.log(`${s.status}: ${s.jobs} jobs ${JSON.stringify(s.by_status)} compiled ${s.compiled}; empty-frame jobs ${s.empty_frame_ranges_with_triggers} → ${rel(out)}`); process.exit(0); }
    if (cmd === "status") { const s = JSON.parse(fs.readFileSync(path.join(out, "OUTBOX_INDEX.json"), "utf8")); console.log(`${s.status}: ${s.jobs} jobs ${JSON.stringify(s.by_status)}`); process.exit(0); }
    if (cmd === "submit" && film && get("--job")) { const r = show(await I.submitJob({ film, out, job: get("--job") })); process.exit(r.status.startsWith("PIXELS") || r.status.startsWith("ALREADY") ? 0 : 3); }
    if (cmd === "export-gpt-job") { const G = await import("../art_bridge/gpt_handoff.mjs"), r = await G.exportGptJob({ film, out, job: get("--job"), stage: +(get("--stage") || 1) }); show({ zip: r.zip, handoff_id: r.handoff_id, instructions: "WHAT_TO_DO_IN_CHATGPT.md inside the zip" }); process.exit(0); }
    if (cmd === "import-gpt-candidates") { const G = await import("../art_bridge/gpt_handoff.mjs"), r = show(G.importGptCandidates({ film, out, bundleDir: get("--bundle") })); process.exit(r.status === "CANDIDATES_RECEIVED_PENDING_SELECTION" ? 0 : 1); }
    if (cmd === "select-candidate") { show(I.selectStageCandidate({ out, job: get("--job"), stage: +get("--stage"), candidateId: get("--candidate") })); process.exit(0); }
    if (cmd === "ingest-master") { const r = show(await I.ingestMaster({ film, asset: get("--asset"), file: get("--file"), landmarks: get("--landmarks"), provenance: get("--provenance"), outbox: out })); process.exit(r.status === "REGISTERED_PENDING_REVIEW" ? 0 : 1); }
    if (cmd === "check-design" || cmd === "review-design") { // Stage 3 contract: BEFORE gate report, and the art director's design decision (HUMAN only with --human on an interactive TTY)
      const C = await import("../art_bridge/art_contract.mjs"), FILM = path.resolve(film), doc = JSON.parse(fs.readFileSync(path.join(FILM, "handoff", "ART_AND_MOTION_MANIFEST_V2.json"), "utf8")), job = (await I.planJobs({ film: FILM })).jobs.find((j) => j.root_dependency === get("--asset"));
      if (!job) throw new Error(`no planned job for ${get("--asset")}`);
      const masterJob = job.derived_from ? (await I.planJobs({ film: FILM })).jobs.find((j) => j.root_dependency === job.derived_from) : null;
      if (cmd === "check-design") { const { applicability_table, ...g } = C.gateForJob({ film: FILM, doc, job, masterJob }); show(g); process.exit(g.pass ? 0 : 1); }
      show(await C.approveDesign({ film: FILM, doc, job, masterJob, reviewer: get("--reviewer"), verdict: get("--verdict"), notes: get("--notes") || "", scope_note: get("--scope-note") || "", human: a.includes("--human") })); process.exit(0); }
    if (cmd === "review-story" || cmd === "review-direction") { const C = await import("../art_bridge/art_contract.mjs"); show(await C.approveScope({ film, scope: cmd.split("-")[1], reviewer: get("--reviewer"), verdict: get("--verdict"), notes: get("--notes") || "", human: a.includes("--human") })); process.exit(0); }
    if (cmd === "review-art") { const AR = await import("../art_bridge/art_review.mjs"), RM = await import("../art_bridge/repair_memory.mjs"), FILM = path.resolve(film), design = JSON.parse(fs.readFileSync(path.join(FILM, "art_designs", `${get("--asset")}.design.json`), "utf8"));
      const packet = AR.buildReviewPacket({ candidate: get("--candidate"), design, outDir: path.join(FILM, "reviews", "packets", path.basename(get("--candidate"), ".png")), intendedHeightPx: +(get("--height") || 600), repo: REPO });
      const defects = get("--defects") ? JSON.parse(fs.readFileSync(get("--defects"), "utf8")) : [];
      const r = await AR.recordArtReview({ film: FILM, candidateSha: packet.candidate_sha256, packet, design, reviewer: get("--reviewer"), verdict: get("--verdict"), defects, human: a.includes("--human") });
      for (const x of r.repair_inputs) RM.recordFailure(FILM, { failure_id: `ART-${x.candidate_sha256.slice(0, 10)}-${x.method_id}`, failure_class: x.failure_class, applicability: { method_id: x.method_id, family: design.art_family }, invariant: `the ${x.method_id} decision is visible in the delivered pixels`, producer: `art_designs/${get("--asset")}.design.json#${x.method_id}`, root_mechanism: x.edited_decision, before: { input_hash: x.candidate_sha256, frames_or_pixels: [x.region_px] }, status: "UNRESOLVED" });
      show(r); process.exit(0); }
    if (cmd === "review-master") { show(await I.reviewMaster({ film, identity: get("--identity"), reviewer: get("--reviewer"), verdict: get("--verdict"), notes: get("--notes") || "", scope_note: get("--scope-note") || "" })); process.exit(0); }
    if (cmd === "ingest-part") { const r = show(await (/\.svg$/i.test(get("--file") || "") ? I.ingestVectorPart : I.ingestPart)({ film, asset: get("--asset"), file: get("--file"), landmarks: get("--landmarks"), provenance: get("--provenance"), outbox: out })); process.exit(r.status === "REGISTERED_PENDING_REVIEW" ? 0 : 1); }
    if (cmd === "review-part") { show(await I.reviewPart({ film, asset: get("--asset"), reviewer: get("--reviewer"), verdict: get("--verdict"), notes: get("--notes") || "", scope_note: get("--scope-note") || "" })); process.exit(0); }
    if (cmd === "approve-state") { show(await I.approveState({ film, rig: get("--rig"), state: get("--state"), reviewer: get("--reviewer"), verdict: get("--verdict"), scope_note: get("--scope-note") || "" })); process.exit(0); }
    if (cmd === "approve-edge") { show(await I.approveStateEdge({ film, rig: get("--rig"), from: get("--from"), to: get("--to"), reviewer: get("--reviewer"), verdict: get("--verdict"), scope_note: get("--scope-note") || "" })); process.exit(0); }
  } catch (e) { console.error(`REFUSED: ${e.message}`); process.exit(1); }
  console.error("usage: art_outbox.mjs export|resume --film DIR | status | submit --film DIR --job ID | ingest-master|ingest-part --film DIR --asset ID --file PNG --landmarks JSON --provenance P | check-design|review-design --film DIR --asset ID [--human] | review-master --identity ID | review-part --asset ID | approve-state --rig R --state S | approve-edge --rig R --from S --to S  (+ --reviewer NAME --verdict V)"); process.exit(2);
}
